// 입력 데이터 검증 및 전처리
const inputData = $input.all()[0].json;

// 샘플 데이터가 없으면 기본 데이터 생성
let dataToProcess = inputData.data || [
  { id: 1, name: '김철수', age: 30, department: '개발팀', salary: 5000 },
  { id: 2, name: '이영희', age: 28, department: '디자인팀', salary: 4500 },
  { id: 3, name: '박민수', age: 35, department: '마케팅팀', salary: 5500 },
  { id: 4, name: '최지연', age: 32, department: '개발팀', salary: 5200 }
];

// 변환 모드 확인 (json-to-csv 또는 csv-to-json)
const mode = inputData.mode || 'json-to-csv';

return [{
  json: {
    originalData: dataToProcess,
    mode: mode,
    timestamp: new Date().toISOString(),
    inputType: Array.isArray(dataToProcess) ? 'array' : 'object'
  }
}];

// JSON to CSV 변환
const data = $input.all()[0].json;
const records = data.originalData;

if (!Array.isArray(records) || records.length === 0) {
  return [{ json: { error: 'Invalid data format', data: data } }];
}

// CSV 헤더 생성 (첫 번째 객체의 키들)
const headers = Object.keys(records[0]);
const csvHeader = headers.join(',');

// CSV 데이터 행 생성
const csvRows = records.map(record => {
  return headers.map(header => {
    const value = record[header];
    // 문자열에 쉼표가 있으면 따옴표로 감싸기
    if (typeof value === 'string' && value.includes(',')) {
      return `"${value}"`;
    }
    return value;
  }).join(',');
});

// 전체 CSV 문자열 생성
const csvString = [csvHeader, ...csvRows].join('\n');

return [{
  json: {
    originalData: records,
    csvString: csvString,
    headers: headers,
    rowCount: records.length,
    conversion: 'json-to-csv',
    success: true
  }
}];

// CSV to JSON 변환 (역변환 테스트)
const data = $input.all()[0].json;
const csvString = data.csvString;

if (!csvString) {
  return [{ json: { error: 'No CSV data to convert' } }];
}

// CSV 파싱
const lines = csvString.split('\n').filter(line => line.trim());
const headers = lines[0].split(',');
const dataRows = lines.slice(1);

// JSON 객체 배열로 변환
const jsonArray = dataRows.map(row => {
  const values = row.split(',');
  const obj = {};

  headers.forEach((header, index) => {
    let value = values[index];

    // 따옴표 제거
    if (value && value.startsWith('"') && value.endsWith('"')) {
      value = value.slice(1, -1);
    }

    // 숫자 변환 시도
    if (value && !isNaN(value) && !isNaN(parseFloat(value))) {
      value = parseFloat(value);
    }

    obj[header] = value;
  });

  return obj;
});

return [{
  json: {
    originalCsv: csvString,
    convertedJson: jsonArray,
    headers: headers,
    recordCount: jsonArray.length,
    conversion: 'csv-to-json',
    success: true
  }
}];

// 변환 결과 요약 및 통계
const jsonToCsvData = $input.all()[0].json;
const csvToJsonData = $input.all()[1].json;

// 변환 정확성 검증
const originalCount = jsonToCsvData.originalData.length;
const finalCount = csvToJsonData.convertedJson.length;
const isAccurate = originalCount === finalCount;

// 샘플 비교 (첫 번째 레코드)
const originalSample = jsonToCsvData.originalData[0];
const convertedSample = csvToJsonData.convertedJson[0];

const result = {
  timestamp: new Date().toISOString(),
  transformationSummary: {
    originalRecords: originalCount,
    finalRecords: finalCount,
    accuracy: isAccurate ? '100%' : `${Math.round(finalCount/originalCount*100)}%`,
    dataIntegrity: isAccurate ? 'PASS' : 'FAIL'
  },
  sampleComparison: {
    original: originalSample,
    afterRoundTrip: convertedSample,
    fieldsMatch: Object.keys(originalSample).length === Object.keys(convertedSample).length
  },
  csvPreview: jsonToCsvData.csvString.split('\n').slice(0, 3).join('\n') + '...',
  conversionFlow: 'JSON → CSV → JSON',
  status: isAccurate ? 'SUCCESS' : 'WARNING'
};

return [{ json: result }];
